    <style>
        *{box-sizing:border-box}:root{--p:#6246e5;--p2:#4f35c8;--navy:#19133f;--bg:#f4f6fb;--text:#20263a;--muted:#718096;--border:#e2e6ef;--green:#15965e;--greenbg:#eafaf2;--blue:#1680e7;--bluebg:#ebf4ff;--shadow:0 14px 36px rgba(31,41,55,.08)}html{-webkit-text-size-adjust:100%;text-rendering:optimizeLegibility}body{margin:0;font-family:"Segoe UI",Inter,Roboto,Arial,sans-serif;background:var(--bg);color:var(--text);-webkit-font-smoothing:antialiased}.topbar{height:72px;background:linear-gradient(100deg,#734bea,#5d40d0 60%,#4d35bd);display:flex;align-items:center;justify-content:space-between;padding:0 24px;color:#fff;position:sticky;top:0;z-index:20;box-shadow:0 8px 24px rgba(79,54,195,.22)}.brand{display:flex;align-items:center;gap:12px;font-size:21px;font-weight:900}.brand-icon{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:rgba(255,255,255,.15);font-size:20px}.top-right{display:flex;align-items:center;gap:14px;font-size:14px;font-weight:800}.logout{border:0;background:rgba(255,255,255,.16);color:#fff;padding:10px 15px;border-radius:10px;font-weight:900}.layout{display:flex;min-height:calc(100vh - 72px)}.sidebar{width:250px;flex:0 0 250px;background:linear-gradient(180deg,#241b4d,#2d205d);color:#fff;padding:18px 12px;position:sticky;top:72px;height:calc(100vh - 72px);overflow:auto}.sidebar-title{font-size:11px;font-weight:900;letter-spacing:1px;color:#cfc8ef;text-transform:uppercase;padding:0 10px 12px}.staff-box{display:flex;align-items:center;gap:11px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.09);padding:12px;border-radius:15px;margin-bottom:15px}.staff-avatar{width:43px;height:43px;border-radius:13px;background:linear-gradient(135deg,#8d70f4,#5e43d7);display:grid;place-items:center;font-weight:900}.staff-name{font-weight:900;font-size:14px}.staff-code{font-size:11px;color:#bbb2df;margin-top:2px;font-weight:700}.menu{display:flex;flex-direction:column;gap:5px}.menu a{display:flex;align-items:center;gap:10px;text-decoration:none;color:#f7f4ff;padding:11px 12px;border-radius:11px;font-size:13px;font-weight:800}.menu a:hover,.menu a.active{background:linear-gradient(90deg,#6948db,#7751ec);box-shadow:0 8px 18px rgba(71,46,170,.28)}.menu-icon{width:23px;text-align:center;font-size:16px}.soon{margin-left:auto;font-size:9px;padding:3px 6px;border-radius:999px;background:rgba(255,255,255,.1);color:#cbc4ea;font-weight:900;text-transform:uppercase}.content{flex:1;min-width:0;padding:24px;background:radial-gradient(circle at 100% 0%,rgba(98,70,229,.09),transparent 23%),linear-gradient(180deg,#f9fafc,#f0f3f8)}.page-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.eyebrow{margin:0 0 5px;color:var(--p);font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:1px}.page-head h1{margin:0;font-size:30px;line-height:1.15;font-weight:950;letter-spacing:-.5px}.subtitle{margin:8px 0 0;color:var(--muted);font-size:14px;font-weight:600}.assignment{background:#fff;border:1px solid #ddd7fa;border-radius:13px;padding:11px 14px;color:var(--p2);font-size:12px;font-weight:900;box-shadow:0 8px 20px rgba(31,41,55,.05);white-space:nowrap}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;margin-bottom:18px}.stat{background:#fff;border:1px solid var(--border);border-radius:17px;padding:16px;box-shadow:var(--shadow);position:relative}.stat:nth-child(1){border-top:4px solid var(--p)}.stat:nth-child(2){border-top:4px solid var(--green)}.stat:nth-child(3){border-top:4px solid #f59e0b}.stat:nth-child(4){border-top:4px solid #06a6b7}.stat:nth-child(5){border-top:4px solid var(--blue)}.stat-label{font-size:11px;color:var(--muted);font-weight:900;text-transform:uppercase;letter-spacing:.6px}.stat-value{margin-top:5px;font-size:29px;font-weight:950;color:var(--navy)}.panel{background:#fff;border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow);overflow:hidden}.panel-head{padding:18px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;gap:15px;align-items:center}.panel-title{margin:0;font-size:19px;font-weight:950}.panel-help{margin:5px 0 0;color:var(--muted);font-size:12px;font-weight:600}.filters{display:grid;grid-template-columns:1.4fr repeat(4,1fr) auto;gap:10px;padding:16px 20px;background:#fbfcfe;border-bottom:1px solid var(--border);align-items:end}.field label{display:block;margin-bottom:6px;font-size:11px;font-weight:900;color:#596579;text-transform:uppercase;letter-spacing:.5px}.field input,.field select{width:100%;height:43px;border:1px solid #d9deea;border-radius:11px;background:#fff;padding:0 12px;font-family:inherit;font-size:13px;font-weight:650}.btn{height:43px;border:0;border-radius:11px;padding:0 16px;font-family:inherit;font-size:12px;font-weight:900;cursor:pointer}.primary{background:linear-gradient(135deg,#6e4be4,#5136c9);color:#fff}.reset{display:inline-flex;align-items:center;justify-content:center;background:#fff;color:#5f687b;border:1px solid #dfe3ea;text-decoration:none}.table-wrap{overflow:auto}table{width:100%;min-width:1250px;border-collapse:collapse}th{padding:13px 14px;background:linear-gradient(180deg,#6246e5,#5136c9);color:#fff;text-align:left;font-size:11px;font-weight:950;text-transform:uppercase;letter-spacing:.35px}td{padding:14px;border-bottom:1px solid #edf0f4;font-size:13px;font-weight:650;color:#2c3650;vertical-align:middle}tbody tr:hover{background:#fbfaff}.student{display:flex;align-items:center;gap:10px;min-width:235px}.photo,.fallback{width:46px;height:54px;border-radius:10px;flex:0 0 46px}.photo{object-fit:cover;border:2px solid #ece8ff}.fallback{display:grid;place-items:center;background:linear-gradient(135deg,#e1dbff,#9d8ae7);color:#4c35b7;font-weight:950}.student-name{font-size:14px;font-weight:900;color:#1e2740}.student-sub{font-size:11px;color:#788397;margin-top:2px}.code{display:inline-block;padding:5px 8px;border-radius:8px;background:#f0ecff;color:var(--p2);font-size:10px;font-weight:950}.num{font-size:14px;font-weight:950;color:var(--navy)}.status{display:inline-flex;padding:6px 9px;border-radius:999px;background:var(--greenbg);color:var(--green);font-size:10px;font-weight:950;text-transform:uppercase}.empty{text-align:center;padding:60px 20px}.empty-icon{width:65px;height:65px;border-radius:21px;margin:0 auto 12px;background:#eafaf2;display:grid;place-items:center;font-size:29px}.empty h3{margin:0;font-size:18px;font-weight:950}.empty p{margin:7px 0 0;color:var(--muted);font-size:13px}.alert{margin-bottom:16px;padding:13px 15px;border-radius:13px;font-size:13px;font-weight:750;background:#eafaf2;color:#0c7046;border:1px solid #bfead4}.pagination-wrap{padding:15px 20px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--border)}.pagination-info{font-size:12px;color:var(--muted);font-weight:650}.pagination{display:flex;gap:6px}.pagination a,.pagination span{min-width:34px;height:34px;border:1px solid #dfe3ea;background:#fff;color:#576175;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;text-decoration:none;font-size:12px;font-weight:900}.pagination .active{background:var(--p);color:#fff;border-color:var(--p)}@media(max-width:1200px){.stats{grid-template-columns:repeat(3,minmax(0,1fr))}.filters{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:850px){.sidebar{width:220px;flex-basis:220px}.content{padding:18px}.page-head{flex-direction:column}}@media(max-width:700px){.layout{display:block}.sidebar{position:static;width:auto;height:auto;display:none}.content{padding:14px}.stats{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr}.topbar{padding:0 14px}.top-right>span{display:none}.brand{font-size:17px}.page-head h1{font-size:25px}}
    </style>
