<div class="layout"><aside class="sidebar"><div class="sidebar-title">Staff Menu</div>@php $staffName=auth()->user()->name??'Staff';$initials=collect(preg_split('/\s+/',trim($staffName)))->filter()->map(fn($p)=>strtoupper(substr($p,0,1)))->take(2)->implode('');$today=now()->toDateString();$activePermissionKeys=$staffProfile->permissions()->where('is_active',true)->where(function($q)use($today){$q->whereNull('start_date')->orWhereDate('start_date','<=',$today);})->where(function($q)use($today){$q->whereNull('end_date')->orWhereDate('end_date','>=',$today);})->pluck('permission_key')->flip();@endphp<div class="staff-box"><div class="staff-avatar">{{ $initials?:'ST' }}</div><div><div class="staff-name">{{ $staffName }}</div><div class="staff-code">{{ $staffProfile->employee_code??'-' }}</div></div></div><nav class="menu"><a href="{{ route('staff.dashboard') }}"><span class="menu-icon">🏠</span><span>Dashboard</span></a>@if(isset($activePermissionKeys['new_applicants']))<a href="{{ route('staff.applications.index') }}"><span class="menu-icon">📝</span><span>New Applicants</span></a>@endif @if(isset($activePermissionKeys['registered_applicants']))<a href="{{ route('staff.registered-applicants.index') }}"><span class="menu-icon">🎓</span><span>Registered Applicants</span></a><a class="active" href="{{ route('staff.college-students.index') }}"><span class="menu-icon">👨‍🎓</span><span>College Students</span></a>@endif @if(isset($activePermissionKeys['offline_fee_verification']))<a href="{{ route('staff.fee-verification.index') }}"><span class="menu-icon">🧾</span><span>Offline Fee Verification</span></a>@endif @if(isset($activePermissionKeys['manage_attendance']))<a href="#" onclick="return false"><span class="menu-icon">📊</span><span>Manage Attendance</span><span class="soon">Soon</span></a>@endif @if(isset($activePermissionKeys['previous_attendance']))<a href="#" onclick="return false"><span class="menu-icon">📁</span><span>Previous Attendance</span><span class="soon">Soon</span></a>@endif @if(isset($activePermissionKeys['marksheet_management']))<a href="#" onclick="return false"><span class="menu-icon">📄</span><span>Marksheet Management</span><span class="soon">Soon</span></a>@endif</nav></aside>
