<form method="GET" action="{{ route('staff.college-students.index') }}" class="filters"><div class="field"><label>Search</label><input name="search" value="{{ $search }}" placeholder="College no., roll no., student name, phone"></div><div class="field"><label>Academic Session</label><select name="session_id"><option value="">All Sessions</option>@foreach($sessionOptions as $session)<option value="{{ $session->id }}" {{ $selectedSession===$session->id?'selected':'' }}>{{ $session->name }}</option>@endforeach</select></div><div class="field"><label>Course / Programme</label><select name="course_id"><option value="">All Courses</option>@foreach($courseOptions as $course)<option value="{{ $course->id }}" {{ $selectedCourse===$course->id?'selected':'' }}>{{ $course->code }} — {{ $course->name }}</option>@endforeach</select></div><div class="field"><label>Year</label><select name="year_number"><option value="">All Years</option>@foreach([1=>'1st Year',2=>'2nd Year',3=>'3rd Year',4=>'4th Year'] as $v=>$l)<option value="{{ $v }}" {{ $selectedYear===$v?'selected':'' }}>{{ $l }}</option>@endforeach</select></div><div class="field"><label>Semester</label><select name="semester_id"><option value="">All Semesters</option>@foreach($semesterOptions as $semester)<option value="{{ $semester->id }}" {{ $selectedSemester===$semester->id?'selected':'' }}>{{ $semester->name }}</option>@endforeach</select></div><div style="display:flex;gap:7px"><button class="btn primary" type="submit">Filter</button><a class="btn reset" href="{{ route('staff.college-students.index') }}">Reset</a></div></form>
@if($students->count())<div class="table-wrap"><table><thead><tr><th>S.No.</th><th>College No.</th><th>Roll No.</th><th>Student</th><th>Course / Programme</th><th>Session</th><th>Year / Semester</th><th>Enrollment Date</th><th>Status</th></tr></thead><tbody>@foreach($students as $index=>$enrollment)@php $student=$enrollment->student;$profile=$student?->studentProfile;$photo=$profile?->student_photo_path;$initials=collect(preg_split('/\s+/',trim($student?->name??'Student')))->filter()->map(fn($p)=>strtoupper(substr($p,0,1)))->take(2)->implode('');@endphp<tr><td>{{ $students->firstItem()+$index }}</td><td><div class="num">{{ $enrollment->college_number }}</div></td><td><div class="num">{{ $enrollment->roll_number }}</div></td><td><div class="student">@if($photo)<img class="photo" src="{{ asset('storage/'.$photo) }}" alt="Student Photo">@else<div class="fallback">{{ $initials?:'ST' }}</div>@endif<div><div class="student-name">{{ $student?->name??'-' }}</div><div class="student-sub">{{ $student?->phone??'-' }}<br>{{ $student?->email??'-' }}</div></div></div></td><td><span class="code">{{ $enrollment->course?->code??'-' }}</span><div style="margin-top:5px">{{ $enrollment->course?->name??'-' }}</div></td><td>{{ $enrollment->academicSession?->name??'-' }}</td><td><strong>Year {{ $enrollment->year_number }}</strong><div class="student-sub">{{ $enrollment->currentSemester?->name??'Yearly Programme' }}</div></td><td>{{ $enrollment->enrollment_date?->format('d-m-Y') ?? '-' }}</td><td><span class="status">● ACTIVE STUDENT</span></td></tr>@endforeach</tbody></table></div><div class="pagination-wrap"><div class="pagination-info">Showing {{ $students->firstItem() }}–{{ $students->lastItem() }} of {{ $students->total() }}</div><div class="pagination">@if($students->onFirstPage())<span>‹</span>@else<a href="{{ $students->previousPageUrl() }}">‹</a>@endif@foreach($students->getUrlRange(max(1,$students->currentPage()-2),min($students->lastPage(),$students->currentPage()+2)) as $page=>$url)@if($page==$students->currentPage())<span class="active">{{ $page }}</span>@else<a href="{{ $url }}">{{ $page }}</a>@endif@endforeach@if($students->hasMorePages())<a href="{{ $students->nextPageUrl() }}">›</a>@else<span>›</span>@endif</div></div>@else<div class="empty"><div class="empty-icon">👨‍🎓</div><h3>No College Students Found</h3><p>Students will appear here only after the first fee verification is completed and their enrollment is created.</p></div>@endif
